    #if !CC_SURFACES_USE_LEGACY_COMPATIBLE_LIGHTING && !CC_IBL_CONVOLUTED
      roughness = RoughnessToPerceptualRoughness(roughness);
    #endif
    vec4 envmap = fragTextureLod(tex, R, roughness * (mipCount - 1.0));
