        if (clipPos.x >= layerThreshold && clipPos.x <= (1.0 - layerThreshold) &&
            clipPos.y >= layerThreshold && clipPos.y <= (1.0 - layerThreshold) &&
            clipPos.z >= 0.0 && clipPos.z <= 1.0 && i == level) {
